"The log to the left side of the page": "Лог — до лівого краю сторінки",
"How wide the adapter's change is: 16 for one voice or instrument, 32 for a style, 64 for many voices, 128 at most.": "Наскільки широко адаптер змінює ваги: 16 для одного голосу чи інструмента, 32 для стилю, 64 для багатьох голосів, 128 щонайбільше.",
"Whether the music half learns (the part that writes the song's tokens), and how hard its lesson pulls against the anchor: 0 leaves it as the base, a timbre only; raise it for diction and style. What counts is the anchor's share of it, not its size.": "Чи вчиться музична половина (та, що пише токени пісні) і як сильно її урок тягне проти якоря: 0 лишає її базовою, лише тембр; підніми для дикції та стилю. Рахується частка якоря від неї, а не її величина.",
"Pulls the music half back toward the base model, so it keeps what the set does not show. Read it as a share of the AR weight: a tenth lets it move, as much as the weight holds it near the base. Nothing at AR weight 0.": "Тягне музичну половину назад до базової моделі, щоб вона зберегла те, чого в наборі немає. Читай його як частку Ваги AR: десята частка дає рухатися, рівний вазі тримає біля бази. За Ваги AR 0 нічого не робить.",
"The music half's learning rate as a share of the one above: the knob that makes it learn faster or slower (0.5: half as fast). It learns a small set by heart quickly.": "Швидкість навчання музичної половини як частка тієї, що вище: ручка, від якої вона вчиться швидше чи повільніше (0.5 — удвічі повільніше). Малий набір вона швидко завчає напам'ять.",
"How they work ›": "Як вони працюють ›",
"The music half's three knobs: the guide": "Три ручки музичної половини: у гайді",
