"The studio's approved sets, as their author published them. Each comes in as a workspace of its own, locked against deletion: its takes as MP3 with their covers, titles and notes. Only what you ask for is downloaded.": "Схвалені набори студії такими, якими їх опублікував автор. Кожен приходить окремим простором, захищеним від видалення: семпли в MP3 з обкладинками, назвами й нотатками. Завантажується лише те, що ти попросиш.",
