"“{0}” is here already": "«{0}» уже тут",
"Restoring brings back the copy published on Hugging Face: the takes it lacks come again, titles and notes return to the published ones, and what was added to it leaves the workspace (those takes stay in the library; its own sections stay). To keep yours as it is: Cancel, rename your workspace (the ⋯ beside its name, then Rename…), and Get again: the original comes in beside it under its own name.": "Відновлення повертає копію, опубліковану на Hugging Face: семпли, яких бракує, приходять знову, назви й нотатки повертаються до опублікованих, а додане виходить із простору (ці семпли лишаються в бібліотеці; його власні підрозділи лишаються).\n\nЩоб зберегти своє як є: «Скасувати», перейменуй свій простір (⋯ біля його назви, потім «Перейменувати…») і знову «Взяти»: оригінал прийде поруч, під власною назвою.",
"Restore the original": "Повернути оригінал",
