"Its takes stay as they are: they are heard and read, never changed, moved or thrown away, and they leave All Workspaces and the search (a take also in a workspace that is not frozen stays there). The workspace greys out; Unfreeze in its ⋯ menu brings everything back.": "Його семпли лишаться як є: їх можна слухати й читати, але не змінювати, не переміщувати й не викидати, і вони зникають з «Усі простори» та з пошуку (семпл, що є і в незамороженому просторі, лишається там). Простір сіріє; «Розморозити» в його меню ⋯ повертає все.",
