"The instruments' covers are painted by an image model: some show an instrument not quite as it really is; the styles' covers are each take's own score.": "Обкладинки інструментів малює модель зображень: на деяких інструмент не зовсім такий, як насправді; обкладинки стилів — власна партитура кожного семплу.",
