"red": "червоним",
": not played when named alone": ": не звучить, коли названий сам",
"The pictures": "Картинки",
"painted by an image model: some show an instrument not quite as it really is": "їх малює модель зображень: на деяких інструмент не зовсім такий, як насправді",
"How the probes were made": "Як робилися проби",
"What YuE2 was asked to play, one instrument or one style at a time, in probes of two minutes (one minute for the first ones), two seeds each, A and B. Some probes are superb, and A and B agree, yet the instrument is not the one asked for. An instrument shapes the style of the whole piece: naming one moves the arrangement too. A crackle or a rustle of paper, as on a worn record, is an unlucky seed: make it again on another.": "Що YuE2 просили зіграти, по одному інструменту чи стилю за раз, пробами по дві хвилини (перші — по хвилині), по два сіди на кожну, A і B. Бувають проби чудові, A і B сходяться, а інструмент не той, що просили. Інструмент формує стиль усієї речі: назвавши його, рухаєш і аранжування. Тріск або шелест паперу, як на заїждженій платівці, — невдалий сід: зроби наново на іншому.",
"What YuE2 was asked to play, one instrument or one style at a time, in probes of two minutes (one minute for the first ones), two seeds each, A and B. Some probes are superb, and A and B agree, yet the instrument is not the one asked for.": "Що YuE2 просили зіграти, по одному інструменту чи стилю за раз, пробами по дві хвилини (перші — по хвилині), по два сіди на кожну, A і B. Бувають проби чудові, A і B сходяться, а інструмент не той, що просили.",
"An instrument shapes the style of the whole piece: naming one moves the arrangement too.": "Інструмент формує стиль усієї речі: назвавши його, рухаєш і аранжування.",
"A crackle or a rustle of paper, as on a worn record, is an unlucky seed: make it again on another.": "Тріск або шелест паперу, як на заїждженій платівці, — невдалий сід: зроби наново на іншому.",
"{#0} heard by ear": "на слух почуто: {0}",
"Works when asked for as «sambuca - greek strings» (Viktor 13.10.2026: «it played honestly»); as «sambuca strings» it failed. Its A/B made again with these words.": "Виходить, якщо просити «sambuca - greek strings» (Віктор 13.10.2026: «запрацювала чесно»); як «sambuca strings» не виходила. Її A/B зроблено наново з цими словами.",
"Probed many times, without success: YuE2 does not know the shofar. The probes always give another pipe or horn, never a shofar, not even close. Its probes (below) are kept: take one as the horn or trumpet it turned out to be. Its adapter knows it: loras/shofar-yt-r16 at epoch 110, Viktor's ear: «Mind-blowing: no shofar player has heard the like. A whole meditation. One hundred percent a Yemenite shofar, an antelope horn two metres long» (167 overtrained, weak and thin; 66 undertrained, a trumpet in it).": "Пробували багато разів, без успіху: YuE2 не знає шофара. Проби завжди дають іншу дудку чи ріг, ніколи не шофар, навіть близько. Його проби (нижче) залишено: бери їх як той ріг чи трубу, якими вони виявилися. Його адаптер шофар знає: loras/shofar-yt-r16 на епосі 110, вухо Віктора: «Вибух мозку: жоден шофарист такого не чув. Ціла медитація. Стовідсотково єменський шофар, ріг антилопи на два метри» (167 перетренована, слабка й тонка; 66 недотренована, у ній труба).",
"Tested, Failed. Other pipe/horn discovered. B alone comes near a Yemenite shofar, a battle cry: still not a shofar.": "Перевірено, не вийшло. Вийшла інша дудка чи ріг. Лише B наближається до єменського шофара, бойовий клич: і все ж не шофар.",
"Tested, Failed. Other pipe/horn discovered.": "Перевірено, не вийшло. Вийшла інша дудка чи ріг.",
"Tested, Failed. Other pipe/horn discovered. Dross, kept: a spark of heavy rock in it.": "Перевірено, не вийшло. Вийшла інша дудка чи ріг. Шлак, але залишений: у ньому іскра важкого року.",
"Not like a horn either.": "І на ріг не схоже.",
"Failed (Viktor 04.10: «unfortunately, YuE2 has no oboe»): no oboe in its probes.": "Не вийшло (Віктор, 04.10: «на жаль, гобоя в YuE2 немає»): у пробах гобоя немає.",
"No such reed: YuE2 does not play the bassoon. Both probes deleted.": "Такої тростини немає: YuE2 не грає на фаготі. Обидві проби видалено.",
"Failed (Viktor 03.10: «the gong failed; deleting it»): no gong in its probes.": "Не вийшло (Віктор, 03.10: «гонг провалився, видаляю»): у пробах гонга немає.",
"Fails: YuE2 gives no birdsong when asked for it alone (the 60 s probes and the 2-minute ones alike).": "Не виходить: YuE2 не дає співу птахів, коли його просять самого (і хвилинні проби, і двохвилинні).",
