"The time: a 1024² picture through it on an RTX 3090, the studio's own way": "Час: картинка 1024² крізь нього на RTX 3090, як це робить студія",
"non-commercial": "некомерційна",
"its page": "його сторінка",
"An upscale in passes, as Viktor's ComfyUI stack: each pass a model and a size of the picture's own": "Апскейл у кілька проходів, як стек ComfyUI у Віктора: у кожному проході модель і розмір від власного розміру картинки",
"Passes…": "Проходи…",
"Passes": "Проходи",
"Each pass runs its model over the picture as it stands and lands at the picture's own size × its factor (each factor the picture's, not the pass before's): Viktor's ComfyUI stack, CR Apply Multi Upscale. Then the long side, then the colours put back to the picture's.": "Кожен прохід проганяє свою модель по картинці, якою вона є, і лягає у власний розмір картинки × свій множник (кожен множник від картинки, а не від попереднього проходу): стек ComfyUI у Віктора, CR Apply Multi Upscale. Далі довга сторона, далі кольори, повернуті до кольорів картинки.",
"Viktor's Qwen 2512 chain (ComfyUI)": "Ланцюжок Віктора для Qwen 2512 (ComfyUI)",
"The pass's upscaler": "Апскейлер проходу",
"The picture's own size times": "Власний розмір картинки, помножений на",
"Take the pass off": "Прибрати прохід",
